package dev.zomboid.installer;
import java.util.*;
public final class Json {
 private final String s;private int p;private Json(String s){this.s=s;}
 public static Object parse(String s){Json j=new Json(s);Object v=j.value();j.ws();if(j.p!=s.length())throw new IllegalArgumentException("JSON incompleto o sobrante");return v;}
 private void ws(){while(p<s.length()&&Character.isWhitespace(s.charAt(p)))p++;}
 private char next(){if(p==s.length())throw new IllegalArgumentException("JSON truncado");return s.charAt(p++);}
 private Object value(){ws();char c=next();if(c=='{'){Map<String,Object> m=new LinkedHashMap<>();ws();if(p<s.length()&&s.charAt(p)=='}'){p++;return m;}while(true){ws();if(next()!='"')throw new IllegalArgumentException("Clave JSON inválida");String k=string();ws();if(next()!=':')throw new IllegalArgumentException("Falta :");if(m.containsKey(k))throw new IllegalArgumentException("Clave repetida: "+k);m.put(k,value());ws();char end=next();if(end=='}')return m;if(end!=',')throw new IllegalArgumentException("Objeto JSON inválido");}}
 if(c=='['){List<Object> a=new ArrayList<>();ws();if(p<s.length()&&s.charAt(p)==']'){p++;return a;}while(true){a.add(value());ws();char end=next();if(end==']')return a;if(end!=',')throw new IllegalArgumentException("Lista JSON inválida");}}
 if(c=='"')return string();p--;for(String literal:List.of("true","false","null"))if(s.startsWith(literal,p)){p+=literal.length();return literal.equals("null")?null:Boolean.valueOf(literal);}int start=p;while(p<s.length()&&"-+0123456789.eE".indexOf(s.charAt(p))>=0)p++;if(start==p)throw new IllegalArgumentException("Valor JSON inválido");return Double.valueOf(s.substring(start,p));}
 private String string(){StringBuilder b=new StringBuilder();while(true){char c=next();if(c=='"')return b.toString();if(c<32)throw new IllegalArgumentException("Control en JSON");if(c=='\\'){c=next();switch(c){case '"','\\','/'->b.append(c);case 'b'->b.append('\b');case 'f'->b.append('\f');case 'n'->b.append('\n');case 'r'->b.append('\r');case 't'->b.append('\t');case 'u'->{if(p+4>s.length())throw new IllegalArgumentException("Unicode truncado");b.append((char)Integer.parseInt(s.substring(p,p+4),16));p+=4;}default->throw new IllegalArgumentException("Escape JSON inválido");}}else b.append(c);}}
 public static String write(Object v){if(v==null)return "null";if(v instanceof String s){StringBuilder b=new StringBuilder("\"");for(char c:s.toCharArray())switch(c){case '"'->b.append("\\\"");case '\\'->b.append("\\\\");case '\n'->b.append("\\n");case '\r'->b.append("\\r");case '\t'->b.append("\\t");default->{if(c<32)b.append(String.format("\\u%04x",(int)c));else b.append(c);}}return b.append('"').toString();}if(v instanceof Number||v instanceof Boolean)return v.toString();if(v instanceof Map<?,?> m){List<String> a=new ArrayList<>();m.forEach((k,x)->a.add(write(k.toString())+":"+write(x)));return "{"+String.join(",",a)+"}";}if(v instanceof Collection<?> c)return "["+String.join(",",c.stream().map(Json::write).toList())+"]";throw new IllegalArgumentException("No serializable");}
 @SuppressWarnings("unchecked")public static Map<String,Object> object(Object o){if(!(o instanceof Map))throw new IllegalArgumentException("Se esperaba objeto");return (Map<String,Object>)o;}
 @SuppressWarnings("unchecked")public static List<Object> list(Object o){if(!(o instanceof List))throw new IllegalArgumentException("Se esperaba lista");return (List<Object>)o;}
}
